<?php require __DIR__.'/bootstrap.php';$p=db();if(method()==='GET')respond($p->query('SELECT setting_key,setting_value FROM settings')->fetchAll(PDO::FETCH_KEY_PAIR));if(method()==='PUT'){$d=body();$st=$p->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) '.(isPostgres()?'ON CONFLICT (setting_key) DO UPDATE SET setting_value=EXCLUDED.setting_value':'ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)'));foreach(['case_context','monitor_stale_hours','monitor_start_date']as$k)if(isset($d[$k]))$st->execute([$k,clean((string)$d[$k])]);respond(['updated'=>true]);}fail('Método não permitido',405);
